const params=new URLSearchParams(location.search);const requested=(params.get('model')||'').trim().toUpperCase();const itemIndex=Number.parseInt(params.get('item'),10);const modelNode=document.querySelector('[data-product-model]');const imageNode=document.querySelector('[data-product-image]');const categoryNode=document.querySelector('[data-product-category]');const specsNode=document.querySelector('[data-product-specs]');const inquiryNode=document.querySelector('[data-product-inquiry]');
function clean(value){return value.replace(/\s+/g,' ').trim()}
async function loadProduct(){if(!requested&&!Number.isInteger(itemIndex)){modelNode.textContent='Product not selected';return}try{const html=await fetch('drivers.html').then(response=>response.text());const documentCopy=new DOMParser().parseFromString(html,'text/html');const cards=[...documentCopy.querySelectorAll('article.product')];const indexed=Number.isInteger(itemIndex)&&itemIndex>=0&&itemIndex<cards.length?cards[itemIndex]:null;const card=indexed||cards.find(item=>clean(item.querySelector('h3')?.textContent||'').toUpperCase()===requested);if(!card)throw new Error('not found');const model=clean(card.querySelector('h3').textContent);const image=card.querySelector('img');const category=clean(card.querySelector('.eyebrow')?.textContent||'Loudspeaker');modelNode.textContent=model;categoryNode.textContent=category;imageNode.src=image.getAttribute('src');imageNode.alt=`SUNY ${model} loudspeaker`;document.title=`${model} ${category} | SUNY`;document.querySelector('meta[name="description"]').content=`SUNY ${model} ${category} specifications and custom engineering options.`;const rows=[...card.querySelectorAll('dl>div')];specsNode.innerHTML=rows.map(row=>{const dt=clean(row.querySelector('dt')?.textContent||'');const dd=clean(row.querySelector('dd')?.textContent||'');if(dd)return `<div class="spec-row"><dt>${dt}</dt><dd>${dd}</dd></div>`;const match=dt.match(/^(.+?)\s+([^\s].*)$/);return `<div class="spec-row"><dt>${match?.[1]||'Specification'}</dt><dd>${match?.[2]||dt}</dd></div>`}).join('');inquiryNode.href=`contact.html?model=${encodeURIComponent(model)}`;}catch(error){modelNode.textContent=requested;categoryNode.textContent='MODEL NOT FOUND';imageNode.hidden=true;specsNode.innerHTML='<p>We could not load this model. Please return to the product catalog.</p>';}}
loadProduct();
